// ✅ NEW: Wire an AbortSignal into the fetch and abort in teardown.
// The request is cancelled, the promise rejects with AbortError, and
// no setState runs after unmount.
async function loadUser(userId) {
  const ac = new AbortController(); // ✅ NEW: one controller per request
  try {
    const res = await fetch(`/api/users/${userId}`, { signal: ac.signal });
    const data = await res.json();
    setState(data);
  } catch (err) {
    if (err.name === 'AbortError') return; // ✅ NEW: expected cancellation
    throw err; // real failures still propagate
  } finally {
    // In component teardown: ac.abort() cancels the in-flight request.
    ac.abort();
  }
}
